from typing import Optional
from packaging.utils import canonicalize_name

def describe_upload(content_type: str, data: bytes) -> dict:
    # Parse content_type into media type and parameters
    # Example: 'Text/HTML; Charset="utf-8"' -> media_type='text/html', params={'charset': 'utf-8'}
    parts = content_type.split(";")
    media_type = parts[0].strip().lower()
    params = {}
    for param in parts[1:]:
        if '=' in param:
            k, v = param.split("=", 1)
            k = k.strip().lower()
            v = v.strip()
            if v.startswith('"') and v.endswith('"') and len(v) >= 2:
                v = v[1:-1]
            params[k] = v.lower()

    charset = params.get("charset")

    # Detect image type from data signature bytes
    image = None
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        image = "png"
    elif data.startswith(b"\xff\xd8\xff"):
        image = "jpeg"
    elif data.startswith(b"GIF87a") or data.startswith(b"GIF89a"):
        image = "gif"

    return {"mime": media_type, "charset": charset, "image": image}

from packaging.version import Version

def newest_compatible(versions: list[str], minimum: str) -> str | None:
    min_ver = Version(minimum)
    best_version = None
    best_version_obj = None
    for v in versions:
        try:
            ver_obj = Version(v)
        except Exception:
            # Ignore invalid version strings
            continue
        if ver_obj >= min_ver:
            if best_version_obj is None or ver_obj > best_version_obj:
                best_version_obj = ver_obj
                best_version = v
    return best_version

