import asyncio
from typing import Any, Coroutine, List, Optional


def run_with_deadline(coros: List[Coroutine[Any, Any, Any]], seconds: float) -> List[Optional[Any]]:
    """
    Run the given coroutines concurrently from synchronous code, with a deadline.

    Args:
        coros: List of coroutine objects to run concurrently.
        seconds: Timeout in seconds to wait for all coroutines.

    Returns:
        List of results in the same order as input coroutines.
        If a coroutine did not finish within the deadline, its result is None.
    """
    async def _runner(coros: List[Coroutine[Any, Any, Any]], timeout: float) -> List[Optional[Any]]:
        tasks = [asyncio.create_task(coro) for coro in coros]
        done, pending = await asyncio.wait(tasks, timeout=timeout)
        # Cancel all pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion to suppress warnings
        for task in pending:
            try:
                await task
            except asyncio.CancelledError:
                pass
            except Exception:
                # Ignore exceptions from cancellation
                pass
        # Prepare results in input order
        results = []
        for task in tasks:
            if task.done():
                try:
                    results.append(task.result())
                except Exception:
                    # If a coroutine raised, propagate exception
                    raise
            else:
                results.append(None)
        return results

    return asyncio.run(_runner(coros, seconds))

